await using var camera = new FileCamera(@"C:\images\bracket", loop: false);
foreach (var _ in camera.Files)
{
    using var img = await camera.Grab(default);
    using var r = await job.RunAsync(img);
    Console.WriteLine($"{Path.GetFileName(camera.LastFile)}: {r.State} [{string.Join(", ", r.Codes)}] {r.Error}");
}

example.code:
await using IVisionCamera camera = await RtspCamera.OpenAsync("rtsp://192.168.0.10:8554/studio");

using var img = await camera.Grab(ct);          // one fresh frame
using var r = await job.RunAsync(img, ct);

await using var camera = await RtspCamera.OpenAsync("rtsp://192.168.0.10:8554/studio");
try
{
    using var img = await camera.Grab(ct);      // a frame decoded after this call
    using var r = await job.RunAsync(img, ct);
}
catch (IOException ex)
{
    Console.WriteLine(ex.Message);              // the stream stopped: dispose the camera and open it again
}

using var img = VisionImage.Load(@"C:\images\part01.bmp");       // the app owns it
using var r = await job.RunAsync(img);                           // images made inside the run are released by the run

// Outside a run, derived images belong to the caller
using var gray = img.Gray();
using var small = gray.Resize(320, 240);
Cv2.GaussianBlur(small.Mat, small.Mat, new Size(5, 5), 0);       // any OpenCV call on the Mat
var inOriginal = small.ToSource(new Point2d(10, 10));            // the same point in img

using var mat = Cv2.ImRead(path, ImreadModes.Grayscale);     // or a frame from your own camera SDK
using var img = VisionImage.From(mat, new VisionImageInfo { Camera = "cam1", FrameNo = 42 });
using var r = await job.RunAsync(img);

VisionImage? binary = null;
job.Add("holes", roi: () => roi, ctx =>
{
    binary = ctx.Image.Threshold(ThresholdMode.Fixed, 80, invert: true).Keep();   // survives the run
});
using (var r = await job.RunAsync(img)) { }
using (binary) binary?.Save("binary.png");                                         // the app disposes it

public sealed class HoleCount(string name, int expected) : IVisionStep
{
    public string Name { get; } = name;

    public Task RunAsync(VisionContext ctx)
    {
        var holes = Blob.Find(ctx.Image, ThresholdMode.Fixed, threshold: 80, invert: true, minArea: 300);
        ctx.Draw(holes);
        ctx.Value(Name, holes.Length, min: expected, max: expected, code: "HOLE");
        return Task.CompletedTask;
    }
}

job.Add(new HoleCount("left hole", 1), roi: () => VisionRoi.Rect(194, 251, 60, 60));

job.Calibration = VisionCalibration.FromLength(px: 410.9, mm: 90.0);   // a gauge of 90 mm measured as 410.9 px

// in a step
var e = Edge.Caliper(ctx.Image);
ctx.Value("width", ctx.Mm(e), nominal: 90, plus: 1, minus: 1, code: "WIDTH", unit: "mm");

job.Calibration = VisionCalibration.FromLength(px: 410.9, mm: 90.0);   // a gauge of 90 mm measured as 410.9 px

// in a step
var e = Edge.Caliper(ctx.Image);
ctx.Value("width", ctx.Mm(e), nominal: 90, plus: 1, minus: 1, code: "WIDTH", unit: "mm");

job.Add("left hole", roi: () => VisionRoi.Rect(194, 251, 60, 60), ctx =>
{
    var holes = Blob.Find(ctx.Image, ThresholdMode.Fixed, threshold: 80, invert: true, minArea: 300);
    ctx.Draw(holes);                                                       // drawn at the right place on the original image
    ctx.Value("left holes", holes.Length, min: 1, max: 1, code: "HOLE");   // out of range → the step is NG with code HOLE
});

ctx.Value("holes", blobs.Length, min: 4, max: 4, code: "HOLE");
ctx.Value("dark pixels", Brightness.Count(ctx.Image, 0, 100), max: 200, code: "DISCOLOR");
ctx.Value("mean", Brightness.Mean(ctx.Image));                          // recorded, not judged

job.Add("align", pose: "body", (ctx, s) =>
{
    var part = Blob.Find(ctx.Image, s.Body).FirstOrDefault();
    if (part is null) { ctx.Fail("part not found"); return; }
    ctx.SetPose(VisionPose.FromBlob(part, s.BodyRef), s.BodyRef);
});

using var edges = new Mat();                 // your Mat: you dispose it
Cv2.Canny(ctx.Image.Mat, edges, 50, 150);
var img = ctx.From(edges);                   // same coordinates as ctx.Image
ctx.DrawBox(new Rect(10, 10, 20, 20), "here", from: img);

member.example:
한 부품의 두 면이 데이터 개체 하나를 공유합니다.

public sealed class PartData { public double? TopWidth; public double? SideWidth; }

var top = new VisionJob<TopSetup, PartData>("top") { Setup = topSetup }
    .Add("width", roi: s => s.Width, (ctx, s, d) =>
    {
        var e = Edge.Caliper(ctx.Image);
        ctx.Draw(e);
        if (ctx.Value("width", e.Distance, min: 405, max: 417, code: "WIDTH"))
            d.TopWidth = e.Distance;
    });

var data = new PartData();                      // one object per part
using var r1 = await top.RunAsync(topImage, data);
using var r2 = await side.RunAsync(sideImage, data);
var state = VisionResult.Worst(r1, r2);         // Error > Ng > Ok

example.code:
public sealed class BracketSetup
{
    public BlobParams Body { get; set; } = new() { MinArea = 20000 };
    public VisionPose? BodyRef { get; set; }                               // taught on the base image
    public VisionRoi HoleL { get; set; } = VisionRoi.Rect(194, 251, 60, 60);
    public BlobParams Hole { get; set; } = new() { Mode = ThresholdMode.Fixed, Threshold = 80, Invert = true, MinArea = 300 };
}

var job = new VisionJob<BracketSetup>("bracket") { Setup = new BracketSetup() }
    .Add("align", pose: "body", (ctx, s) =>
    {
        var part = Blob.Find(ctx.Image, s.Body).FirstOrDefault();
        if (part is null) { ctx.Fail("part not found"); return; }
        ctx.SetPose(VisionPose.FromBlob(part, s.BodyRef), s.BodyRef);
    })
    .Add("left hole", roi: s => s.HoleL, (ctx, s) =>
    {
        var holes = Blob.Find(ctx.Image, s.Hole);
        ctx.Draw(holes);
        ctx.Value("left holes", holes.Length, min: 1, max: 1, code: "HOLE");
    });

using var img = VisionImage.Load(path);
using var r = await job.RunAsync(img);

var job = new VisionJob("bracket")
    .Add("align", pose: "body", ctx =>
    {
        var part = Blob.Find(ctx.Image, minArea: 20000).FirstOrDefault();
        if (part is null) { ctx.Fail("part not found"); return; }
        ctx.SetPose(VisionPose.FromBlob(part), reference: new VisionPose(330.4, 256.0, 0));
    })
    .Add("left hole", roi: () => VisionRoi.Rect(194, 251, 60, 60), ctx =>
    {
        var holes = Blob.Find(ctx.Image, ThresholdMode.Fixed, threshold: 80, invert: true, minArea: 300);
        ctx.Draw(holes);
        ctx.Value("left holes", holes.Length, min: 1, max: 1, code: "HOLE");
    });

using var img = VisionImage.Load(path);
using var r = await job.RunAsync(img);
Console.WriteLine($"{r.State} [{string.Join(", ", r.Codes)}] {r.Error}");

using var img = await camera.Grab(ct);
using var r = await job.RunAsync(img, ct);
switch (r.State)
{
    case VisionState.Ok: break;
    case VisionState.Ng: Console.WriteLine(string.Join(", ", r.Codes)); break;
    case VisionState.Error: Console.WriteLine(r.Error); break;          // could not inspect — not the same as a reject
}

public sealed class LabelSetup { public VisionModel Logo { get; set; } = new(); public VisionRoi LogoRoi { get; set; } }

// Teaching: cut the region out of the base image, save it under the recipe folder, swap the setup
var edit = VisionSetup.Copy(job.Setup!);
edit.Logo = VisionModel.Teach(baseImage, edit.LogoRoi, recipeFolder, "models/logo.png");
job.Setup = edit;

// Startup: after reading the setup JSON
setup.Logo.Load(recipeFolder);

var edit = VisionSetup.Copy(job.Setup!);
edit.Hole.Threshold = 90;
job.Setup = edit;            // the next run uses the new values

