example.code:
job.Add("tab", roi: () => roi, ctx =>
{
    ctx.Value("mean", Brightness.Mean(ctx.Image), min: 120, max: 220, code: "BRIGHT");
    ctx.Value("dark pixels", Brightness.Count(ctx.Image, 0, 100), max: 200, code: "DISCOLOR");
});

using var model = DefectModel.Load(@"C:\recipes\nut\models\defect-1");

job.Add("defect", roi: () => roi, ctx =>
{
    DefectResult d = model.Classify(ctx.Image);
    ctx.DrawText(new Point2d(4, 16), $"{d.Label} {d.Probability:0.00}");
    ctx.Value("defect probability", d.DefectProbability, max: 0.5, code: d.Defect.ToUpperInvariant());
});

// Teaching: the same ROI crop of every good part
var trained = DiffModel.Train(goodCrops);
trained.Save(recipeFolder, "models/diff");

// A step whose ROI is the one used for training (s.Diff was read with s.Diff.Load(recipeFolder))
job.Add("surface", roi: s => s.SurfaceRoi, (ctx, s) =>
{
    var d = s.Diff.Compare(ctx.Image);
    ctx.Draw(d.Regions);
    ctx.Value("largest difference", d.MaxArea, max: 30, code: "SURFACE", unit: "px²");
});

job.Add("width", roi: () => VisionRoi.Rect(100, 305, 470, 30), ctx =>
{
    var e = Edge.Caliper(ctx.Image, EdgePolarity.BrightObject, minContrast: 8);
    ctx.Draw(e);
    ctx.Value("width", e.Distance, min: 405, max: 417, code: "WIDTH", unit: "px");
});

using var model = OnnxModel.Load(@"C:\models\classifier.onnx", inputWidth: 224, inputHeight: 224, VisionTensorFormat.ImageNet);

OnnxOutputs o = model.Run(image);
OnnxTensor scores = o.Ordered[0];              // or o["output name"]; model.Outputs lists the names
int best = Array.IndexOf(scores.Data, scores.Data.Max());

// Teaching, once, on the base image
var model = RoundModel.Train(baseImage, center: new Point2d(350, 350), innerRadius: 120, outerRadius: 200);

job.Add("align", pose: "nut", ctx =>
{
    var hole = Blob.Find(ctx.Image, ThresholdMode.Fixed, 60, invert: true, minArea: 2000).FirstOrDefault();
    if (hole is null) { ctx.Fail("part not found"); return; }
    var match = model.Find(ctx.Image, hole.Center);
    ctx.Value("match", match.Score, min: 0.5, code: "ALIGN");
    ctx.Judge(!match.Mirrored, "FLIPPED");
    ctx.SetPose(match.Pose, model.ReferencePose);
});
